INSERT INTO questions (category, difficulty, question_text, correct_answer, wrong_answers, language, is_active, explanation) VALUES
('cinema', 5, 'Quel est le seul film à avoir remporté la Palme d''Or, le Lion d''Or et un Oscar du meilleur film ?', 'Aucun film n''a accompli cet exploit', ARRAY['Parasite', 'Amour', 'Le Pianiste'], 'fr', true, 'Aucun film de l''histoire du cinéma n''a remporté ces trois prix prestigieux simultanément.'),
